// `distribution/profile-catalog.json` is GENERATED by this script and is never
// hand-edited. The reviewable source is one file per profile under `profiles/`
// plus the shared shell in `profiles/manifest.json`, so a profile change is a
// small diff in its own file instead of a line inside a 700-line array. Every
// consumer keeps reading the aggregate, which is why it stays committed.

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compareOrdinal, sortedOrdinal } from "./catalog-ordering.mjs";

const defaultRepositoryRoot = resolve(
    fileURLToPath(new URL("..", import.meta.url)),
);

export const profileSourceRoot = "profiles";
export const profileManifestPath = "profiles/manifest.json";
export const profileCatalogPath = "distribution/profile-catalog.json";

/**
 * The audience directory names are the resolver's own vocabulary. `public` and
 * `cratis-engineering` are exactly the audiences `indexProfiles` assigns to
 * `publicProfiles` and `engineeringProfiles`, so the source layout cannot drift
 * into a third name for the same thing.
 */
export const profileAudienceDirectories = Object.freeze([
    Object.freeze({ field: "publicProfiles", directory: "public" }),
    Object.freeze({
        field: "engineeringProfiles",
        directory: "cratis-engineering",
    }),
]);

/**
 * The manifest field the two generated profile arrays follow. The aggregate
 * otherwise emits manifest fields in the manifest's own order, so this is the
 * one placement decision the shell cannot express by itself.
 */
export const profileArraysFollowField = "confidentiality";

function json(value) {
    return `${JSON.stringify(value, null, 2)}\n`;
}

function readJson(path) {
    try {
        return JSON.parse(readFileSync(path, "utf8"));
    } catch (error) {
        throw new Error(`Profile source must be strict JSON: ${path}`, {
            cause: error,
        });
    }
}

function profileFiles(root, relativePath = "") {
    const paths = [];
    for (const entry of readdirSync(join(root, relativePath), {
        withFileTypes: true,
    })) {
        const child = relativePath ? `${relativePath}/${entry.name}` : entry.name;
        if (entry.isDirectory()) paths.push(...profileFiles(root, child));
        else if (entry.isFile() && entry.name.endsWith(".json"))
            paths.push(child);
        else
            throw new Error(
                `Profile source tree contains an unexpected path: ${child}`,
            );
    }
    return sortedOrdinal(paths);
}

/**
 * Reads every profile in one audience directory. A profile's id is its path
 * under that directory, so `profiles/public/cratis/arc.json` must declare
 * `cratis/arc` and nothing else can silently claim that id.
 */
export function readAudienceProfiles(repositoryRoot, directory) {
    const root = join(resolve(repositoryRoot), profileSourceRoot, directory);
    const profiles = profileFiles(root).map((relativePath) => {
        const profile = readJson(join(root, relativePath));
        const expectedId = relativePath.slice(0, -".json".length);
        if (profile.id !== expectedId)
            throw new Error(
                `Profile ${profileSourceRoot}/${directory}/${relativePath} declares id ${profile.id} but its path requires ${expectedId}`,
            );
        return profile;
    });
    return profiles.sort((left, right) =>
        compareOrdinal(left.id, right.id),
    );
}

/**
 * Builds the aggregate profile catalog: the manifest shell in its authored
 * field order, with the two ordinally sorted profile arrays inserted after
 * `confidentiality`.
 */
export function buildProfileCatalog(repositoryRoot = defaultRepositoryRoot) {
    const root = resolve(repositoryRoot);
    const manifest = readJson(join(root, profileManifestPath));
    for (const { field } of profileAudienceDirectories)
        if (field in manifest)
            throw new Error(
                `${profileManifestPath} must not declare ${field}; profiles are one file each under ${profileSourceRoot}/`,
            );
    if (!(profileArraysFollowField in manifest))
        throw new Error(
            `${profileManifestPath} must declare ${profileArraysFollowField}`,
        );
    const catalog = {};
    for (const [field, value] of Object.entries(manifest)) {
        catalog[field] = value;
        if (field !== profileArraysFollowField) continue;
        for (const { field: profileField, directory } of profileAudienceDirectories)
            catalog[profileField] = readAudienceProfiles(root, directory);
    }
    return catalog;
}

function main() {
    const catalog = buildProfileCatalog();
    writeFileSync(join(defaultRepositoryRoot, profileCatalogPath), json(catalog));
    process.stdout.write(
        `Generated profile catalog: ${catalog.publicProfiles.length} public and ${catalog.engineeringProfiles.length} engineering profiles from ${profileSourceRoot}/.\n`,
    );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
